export type IconName = keyof typeof iconPaths;
/** Inline 16px stroke icon that inherits currentColor. */
export const icon = (name: IconName, size = 16): string =>
  `<svg class="icon" aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${iconPaths[name]}</svg>`;
/** CSS mask URL for the same icon. */
export const iconUrl = (name: IconName): string =>
  `url("data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="black" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${iconPaths[name]}</svg>`)}")`;
